-- Profile sections: the rest of each profile bucket, keyed by profile id.
--
-- Generated by supabase/generators/import_profile_sections.py from Claude outputs/audits/
-- FIRESTORE-FULL-DUMP.md, admin/scripts/seed/data/taxonomy-seed.ts and src/data/linked-profiles.ts.
-- Edit the generator, not this file.
--
-- Schema
--   profiles + hourly_rate_paise, budget_tier (budget_type slug), persona_badges, trust_badges,
--             is_verified, is_available. trust_badges and is_verified are admin-only: a signed-in
--             user changing them is refused by trigger.
--   profile_services, profile_experience, profile_gallery, reviews (of a profile),
--   profile_role_details (per role, jsonb), profile_business (1:1), profile_members (team / band
--   lineup), profile_events (shows).
--   Read: rows of public profiles, and your own. Write: owners for their own sections; reviews and
--   admin fields are not client-writable.
--   Money is integer paise; a price with no amount keeps its text in price_note.
--
-- Data
--   Taxonomy: the 25 categories not yet loaded (published).
--   Firebase: rates, budget tiers, badges, verified / available, role details (user fields and
--   role_profiles), service offerings, business / venue details, team and band lineup, shows, and
--   reviews of people. Studio reviews belong to studios and are not here.
--   The 11 linked seed profiles: services, experience, reviews and gallery from their TS sections.
--   Not imported: gender, GSTIN, email.
--
-- Each data block re-reads what it wrote and raises on any difference. Idempotent.

ALTER TABLE public.profiles
  ADD COLUMN IF NOT EXISTS hourly_rate_paise bigint CHECK (hourly_rate_paise >= 0),
  ADD COLUMN IF NOT EXISTS budget_tier text,
  ADD COLUMN IF NOT EXISTS persona_badges text[] NOT NULL DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS trust_badges text[] NOT NULL DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS is_verified boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS is_available boolean NOT NULL DEFAULT true;

-- Admin-granted fields. Signed-in and anonymous callers cannot set or change them; the service role
-- and direct database sessions can.
CREATE OR REPLACE FUNCTION public.profiles_guard_admin_fields()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public
AS $fn$
BEGIN
  IF coalesce(auth.jwt() ->> 'role', '') IN ('authenticated', 'anon') THEN
    IF TG_OP = 'INSERT' AND (NEW.trust_badges <> '{}' OR NEW.is_verified) THEN
      RAISE EXCEPTION 'trust_badges and is_verified are set by MusicLinkd, not by the profile owner';
    END IF;
    IF TG_OP = 'UPDATE' AND (NEW.trust_badges IS DISTINCT FROM OLD.trust_badges
                             OR NEW.is_verified IS DISTINCT FROM OLD.is_verified) THEN
      RAISE EXCEPTION 'trust_badges and is_verified are set by MusicLinkd, not by the profile owner';
    END IF;
  END IF;
  RETURN NEW;
END
$fn$;

DROP TRIGGER IF EXISTS profiles_guard_admin_fields ON public.profiles;
CREATE TRIGGER profiles_guard_admin_fields
  BEFORE INSERT OR UPDATE ON public.profiles
  FOR EACH ROW EXECUTE FUNCTION public.profiles_guard_admin_fields();

-- Readable when the owning profile is public, or it is your own.
CREATE OR REPLACE FUNCTION public.profile_is_readable(p_profile_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $fn$
  SELECT EXISTS (SELECT 1 FROM public.profiles p
                 WHERE p.id = p_profile_id AND (p.visibility = 'public' OR p.id = auth.uid()));
$fn$;
REVOKE ALL ON FUNCTION public.profile_is_readable(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.profile_is_readable(uuid) TO anon, authenticated;

CREATE TABLE IF NOT EXISTS public.profile_services (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  profile_id   uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  name         text NOT NULL,
  description  text,
  price_paise  bigint CHECK (price_paise >= 0),
  price_unit   text,
  price_note   text,
  turnaround   text,
  mode         text,
  availability text,
  sort_order   int NOT NULL DEFAULT 0,
  created_at   timestamptz NOT NULL DEFAULT now(),
  updated_at   timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.profile_experience (
  id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  profile_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  title      text NOT NULL,
  org        text,
  start_year int,
  end_year   int,  -- null: present
  detail     text,
  sort_order int NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK (end_year IS NULL OR start_year IS NULL OR end_year >= start_year)
);

CREATE TABLE IF NOT EXISTS public.profile_gallery (
  id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  profile_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  image_url  text NOT NULL,
  caption    text,
  sort_order int NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.reviews (
  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  target_profile_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  author_profile_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
  author_name       text NOT NULL,
  author_org        text,
  context           text,
  rating            numeric(2,1) NOT NULL CHECK (rating >= 1 AND rating <= 5),
  body              text NOT NULL,
  response          text,
  created_at        timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.profile_role_details (
  profile_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  role_slug  text NOT NULL,
  details    jsonb NOT NULL DEFAULT '{}',
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (profile_id, role_slug)
);

CREATE TABLE IF NOT EXISTS public.profile_business (
  profile_id       uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE,
  business_address text,
  operating_hours  text,
  equipment_list   text[] NOT NULL DEFAULT '{}',
  artist_roster    text[] NOT NULL DEFAULT '{}',
  talent_roster    text[] NOT NULL DEFAULT '{}',
  courses          text[] NOT NULL DEFAULT '{}',
  capacity         int CHECK (capacity >= 0),
  venue_features   text[] NOT NULL DEFAULT '{}',
  updated_at       timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.profile_members (
  id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  profile_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  kind       text NOT NULL CHECK (kind IN ('team', 'lineup')),
  name       text NOT NULL,
  role       text,
  experience text,
  is_leader  boolean NOT NULL DEFAULT false,
  sort_order int NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS public.profile_events (
  id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  profile_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  title      text NOT NULL,
  event_date date,
  venue_name text,
  sort_order int NOT NULL DEFAULT 0
);

CREATE INDEX IF NOT EXISTS profile_services_profile_idx   ON public.profile_services (profile_id, sort_order);
CREATE INDEX IF NOT EXISTS profile_experience_profile_idx ON public.profile_experience (profile_id, sort_order);
CREATE INDEX IF NOT EXISTS profile_gallery_profile_idx    ON public.profile_gallery (profile_id, sort_order);
CREATE INDEX IF NOT EXISTS reviews_target_profile_idx     ON public.reviews (target_profile_id, created_at DESC);
CREATE INDEX IF NOT EXISTS profile_members_profile_idx    ON public.profile_members (profile_id, kind, sort_order);
CREATE INDEX IF NOT EXISTS profile_events_profile_idx     ON public.profile_events (profile_id, event_date);

DO $rls$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['profile_services', 'profile_experience', 'profile_gallery', 'profile_role_details',
                           'profile_business', 'profile_members', 'profile_events'] LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('GRANT SELECT ON public.%I TO anon, authenticated', t);
    EXECUTE format('GRANT INSERT, UPDATE, DELETE ON public.%I TO authenticated', t);
    EXECUTE format('GRANT ALL ON public.%I TO service_role', t);
    EXECUTE format('DROP POLICY IF EXISTS "Readable with its profile" ON public.%I', t);
    EXECUTE format('CREATE POLICY "Readable with its profile" ON public.%I FOR SELECT USING (public.profile_is_readable(profile_id))', t);
    EXECUTE format('DROP POLICY IF EXISTS "Owners write their own" ON public.%I', t);
    EXECUTE format('CREATE POLICY "Owners write their own" ON public.%I FOR ALL TO authenticated USING (auth.uid() = profile_id) WITH CHECK (auth.uid() = profile_id)', t);
  END LOOP;
END
$rls$;

ALTER TABLE public.reviews ENABLE ROW LEVEL SECURITY;
GRANT SELECT ON public.reviews TO anon, authenticated;
GRANT ALL ON public.reviews TO service_role;
DROP POLICY IF EXISTS "Readable with its profile" ON public.reviews;
CREATE POLICY "Readable with its profile" ON public.reviews FOR SELECT
  USING (public.profile_is_readable(target_profile_id));

-- taxonomy categories 1/1 (25 rows)
DO $import$
DECLARE
  payload jsonb := $json$[{"key":"persona_badges","label":"Persona Badges","description":"Self-selected profile tags — proposed starter set, not grounded in existing app data."},{"key":"project_types","label":"Project Types","description":"Portfolio project type — value matches availableProjectTypes in PortfolioData.kt."},{"key":"project_roles","label":"Project Roles","description":"Role a person plays on one project (distinct from person_types, their platform-wide primary role) — matches availableProjectRoles in PortfolioData.kt."},{"key":"booking_statuses","label":"Booking Statuses","description":"Feeds StudioBookingDoc.bookingStatus."},{"key":"studio_amenities","label":"Studio Amenities","description":"Feeds the already-deployed StudioDoc.amenities — matches hardcoded amenity tags in StudioBookingScreens.kt's mock studio data."},{"key":"collaboration_types","label":"Collaboration Types","description":"Feeds ProjectDoc.collaborationType."},{"key":"trust_badges","label":"Trust Badges","description":"Admin-granted badges, distinct from self-selected persona_badges. Feeds UserDoc.trustBadges — security rules block a user from setting this on their own doc."},{"key":"vocal_range","label":"Vocal Range","description":"Singer module (Talent profile). Proposed industry-standard vocabulary."},{"key":"daw_tools","label":"DAW Tools","description":"Engineer module (Talent profile). Proposed industry-standard vocabulary."},{"key":"session_types","label":"Session Types","description":"Studio Booking \"Configure Session\" screen — feeds StudioBookingDoc.sessionType."},{"key":"session_duration_tiers","label":"Session Duration Tiers","description":"Studio Booking \"Configure Session\" screen — feeds StudioBookingDoc.durationTier."},{"key":"studio_services","label":"Studio Services","description":"Studio Discovery filter chips — feeds StudioDoc.services (what a studio offers, distinct from studio_amenities' what it physically has)."},{"key":"singing_styles","label":"Singing Styles","description":"Singer role profile. Proposed vocabulary."},{"key":"lyricist_specializations","label":"Lyricist Specializations","description":"Lyricist role profile. Proposed vocabulary."},{"key":"director_specializations","label":"Director Specializations","description":"Music Director role profile. Proposed vocabulary."},{"key":"composition_styles","label":"Composition Styles","description":"Composer role profile. Proposed vocabulary."},{"key":"engineer_specialties","label":"Engineer Specialties","description":"Sound Engineer role profile. Proposed vocabulary."},{"key":"dj_types","label":"DJ Types","description":"DJ role profile. Proposed vocabulary."},{"key":"verification_id_type","label":"Verification ID Type","description":"Feeds VerificationRequestDoc.verificationIdType."},{"key":"availability_status","label":"Availability Status","description":"Talent availability — feeds UserDoc.sessionAvailability. Canonical 5-value list (a rougher 4-value \"Available/Busy/Touring/Studio Work\" mention elsewhere in this session's history is not a second source — don't seed both)."},{"key":"podcast_categories","label":"Podcast Categories","description":"Podcaster role profile. Proposed vocabulary."},{"key":"marketplace_categories","label":"Marketplace Categories","description":"Feeds the corrected MarketplaceItemDoc.category."},{"key":"equipment_categories","label":"Equipment Categories","description":"Feeds StudioEquipmentItem.category and MarketplaceItemDoc.itemCategory for gear listings — distinct from instruments and studio_amenities."},{"key":"budget_type","label":"Budget Type","description":"Feeds UserDoc.budgetTier — coarse price-tier indicator, separate from the exact hourlyRate figure."},{"key":"opportunity_types","label":"Opportunity Types","description":"Feeds ProjectDoc.opportunityType (Flow 5, Opportunities) — a separate axis from collaboration_types (compensation structure, not opportunity kind). Proposed 2026-08-16, Phase 2, not yet wired into any screen — see docs/04-Wireframes/PRODUCT-SPEC.md §D.6. Group carried in metadata.group rather than a 3rd Firestore level, per the existing sub-area/metadata convention. recording/mixing/mastering deliberately value-aligned with engineer_specialties/studio_services — different axis, same value strings, on purpose."}]$json$;
BEGIN
  INSERT INTO public.taxonomy_categories (key, label, description)
  SELECT r.key, r.label, r.description FROM jsonb_to_recordset(payload) AS r(key text, label text, description text)
  ON CONFLICT (key) DO UPDATE SET label = EXCLUDED.label, description = EXCLUDED.description;
END
$import$;

