"id":"a06e78a7-5430-5005-9476-0fdacbfce4d9","profile_id":"9b76ac6a-6c04-42ae-955f-9e3233b02199","name":"Mastering","description":"Streaming and DDP masters, loudness matched per platform.","price_paise":350000,"price_unit":"song","price_note":null,"turnaround":"2 days","mode":"Remote","availability":"Open","sort_order":1},{"id":"3cec16a2-29e8-52c6-ad4c-a694c5df65aa","profile_id":"2c29531c-68cf-4b7d-84e1-08ae729a6c69","name":"Live Room A","description":"Full-band tracking with drum isolation and an engineer.","price_paise":null,"price_unit":null,"price_note":null,"turnaround":"Book a week ahead","mode":"In person","availability":"Weekday mornings","sort_order":0},{"id":"d163b376-3bbf-5ec4-acaa-79286e5e2c05","profile_id":"2c29531c-68cf-4b7d-84e1-08ae729a6c69","name":"Vocal booth","description":"Vocal and voiceover recording with comping.","price_paise":null,"price_unit":null,"price_note":null,"turnaround":"Same week","mode":"In person","availability":"Open","sort_order":1},{"id":"dfb71d12-c58b-5c2f-b9e8-f79a5464e63f","profile_id":"8a15fc73-c131-46f5-8cba-2c1c96aaa645","name":"Production liaison","description":"Schedules, budgets and deliveries for score and release projects.","price_paise":4000000,"price_unit":"project","price_note":null,"turnaround":"Starts within a week","mode":"Remote · In person","availability":"1 project open","sort_order":0}]$json$;
BEGIN
  INSERT INTO public.profile_services (id, profile_id, name, description, price_paise, price_unit, price_note, turnaround, mode, availability, sort_order)
  SELECT r.id, r.profile_id, r.name, r.description, r.price_paise, r.price_unit, r.price_note, r.turnaround, r.mode, r.availability, r.sort_order FROM jsonb_to_recordset(payload) AS r(id uuid, profile_id uuid, name text, description text, price_paise bigint, price_unit text, price_note text, turnaround text, mode text, availability text, sort_order int)
  ON CONFLICT (id) DO UPDATE SET profile_id = EXCLUDED.profile_id, name = EXCLUDED.name, description = EXCLUDED.description, price_paise = EXCLUDED.price_paise, price_unit = EXCLUDED.price_unit, price_note = EXCLUDED.price_note, turnaround = EXCLUDED.turnaround, mode = EXCLUDED.mode, availability = EXCLUDED.availability, sort_order = EXCLUDED.sort_order;

  IF (SELECT count(*) FROM jsonb_to_recordset(payload) AS r(id uuid, profile_id uuid, name text, description text, price_paise bigint, price_unit text, price_note text, turnaround text, mode text, availability text, sort_order int) JOIN public.profile_services t ON t.id = r.id
      WHERE (t.id, t.profile_id, t.name, t.description, t.price_paise, t.price_unit, t.price_note, t.turnaround, t.mode, t.availability, t.sort_order) IS NOT DISTINCT FROM (r.id, r.profile_id, r.name, r.description, r.price_paise, r.price_unit, r.price_note, r.turnaround, r.mode, r.availability, r.sort_order))
     <> jsonb_array_length(payload) THEN
    RAISE EXCEPTION 'profile_services import: stored rows differ from the payload';
  END IF;
END
$import$;

