BEGIN
  INSERT INTO public.reviews (id, target_profile_id, author_name, author_org, context, rating, body, response)
  SELECT r.id, r.target_profile_id, r.author_name, r.author_org, r.context, r.rating, r.body, r.response FROM jsonb_to_recordset(payload) AS r(id uuid, target_profile_id uuid, author_name text, author_org text, context text, rating numeric, body text, response text)
  ON CONFLICT (id) DO UPDATE SET target_profile_id = EXCLUDED.target_profile_id, author_name = EXCLUDED.author_name, author_org = EXCLUDED.author_org, context = EXCLUDED.context, rating = EXCLUDED.rating, body = EXCLUDED.body, response = EXCLUDED.response;

  IF (SELECT count(*) FROM jsonb_to_recordset(payload) AS r(id uuid, target_profile_id uuid, author_name text, author_org text, context text, rating numeric, body text, response text) JOIN public.reviews t ON t.id = r.id
      WHERE (t.id, t.target_profile_id, t.author_name, t.author_org, t.context, t.rating, t.body, t.response) IS NOT DISTINCT FROM (r.id, r.target_profile_id, r.author_name, r.author_org, r.context, r.rating, r.body, r.response))
     <> jsonb_array_length(payload) THEN
    RAISE EXCEPTION 'reviews import: stored rows differ from the payload';
  END IF;

  UPDATE public.reviews t SET created_at = r.created_at
  FROM jsonb_to_recordset(payload) AS r(id uuid, created_at timestamptz)
  WHERE t.id = r.id AND r.created_at IS NOT NULL;
END
$import$;

