BEGIN
  INSERT INTO public.profile_role_details (profile_id, role_slug, details)
  SELECT r.profile_id, r.role_slug, r.details FROM jsonb_to_recordset(payload) AS r(profile_id uuid, role_slug text, details jsonb)
  ON CONFLICT (profile_id, role_slug) DO UPDATE SET details = EXCLUDED.details;

  IF (SELECT count(*) FROM jsonb_to_recordset(payload) AS r(profile_id uuid, role_slug text, details jsonb) JOIN public.profile_role_details t ON t.profile_id = r.profile_id AND t.role_slug = r.role_slug
      WHERE (t.profile_id, t.role_slug, t.details) IS NOT DISTINCT FROM (r.profile_id, r.role_slug, r.details))
     <> jsonb_array_length(payload) THEN
    RAISE EXCEPTION 'profile_role_details import: stored rows differ from the payload';
  END IF;
END
