"capacity":null,"venue_features":[]},{"profile_id":"512fe131-5518-5678-a35b-d06eb8fa3d12","business_address":"Mumbai, Maharashtra","operating_hours":null,"equipment_list":[],"artist_roster":[],"talent_roster":[],"courses":[],"capacity":null,"venue_features":[]},{"profile_id":"2fac8ef7-d83c-5378-8a74-96263bc168c7","business_address":"Juhu, Mumbai","operating_hours":null,"equipment_list":[],"artist_roster":[],"talent_roster":[],"courses":[],"capacity":null,"venue_features":[]},{"profile_id":"86a5d555-61eb-5619-b452-3a9387baa66f","business_address":"Andheri West, Mumbai","operating_hours":"09:00 AM – 11:00 PM (Mon–Sat)","equipment_list":["SSL 9000J 72-Channel Console","Dolby Atmos 7.1.4 PMC Studio Monitors","Neumann U87/U47/Telefunken ELAM 251"],"artist_roster":[],"talent_roster":[],"courses":[],"capacity":null,"venue_features":[]},{"profile_id":"f2ece64c-c18d-5f28-bc3e-d72e6e25fa69","business_address":null,"operating_hours":null,"equipment_list":[],"artist_roster":[],"talent_roster":[],"courses":[],"capacity":400,"venue_features":["L-Acoustics K3 Line Array","GrandMA3 Lighting Console","Dual HD LED Screen Banners","Backline Included"]}]$json$;
BEGIN
  INSERT INTO public.profile_business (profile_id, business_address, operating_hours, equipment_list, artist_roster, talent_roster, courses, capacity, venue_features)
  SELECT r.profile_id, r.business_address, r.operating_hours, r.equipment_list, r.artist_roster, r.talent_roster, r.courses, r.capacity, r.venue_features FROM jsonb_to_recordset(payload) AS r(profile_id uuid, business_address text, operating_hours text, equipment_list text[], artist_roster text[], talent_roster text[], courses text[], capacity int, venue_features text[])
  ON CONFLICT (profile_id) DO UPDATE SET business_address = EXCLUDED.business_address, operating_hours = EXCLUDED.operating_hours, equipment_list = EXCLUDED.equipment_list, artist_roster = EXCLUDED.artist_roster, talent_roster = EXCLUDED.talent_roster, courses = EXCLUDED.courses, capacity = EXCLUDED.capacity, venue_features = EXCLUDED.venue_features;

  IF (SELECT count(*) FROM jsonb_to_recordset(payload) AS r(profile_id uuid, business_address text, operating_hours text, equipment_list text[], artist_roster text[], talent_roster text[], courses text[], capacity int, venue_features text[]) JOIN public.profile_business t ON t.profile_id = r.profile_id
      WHERE (t.profile_id, t.business_address, t.operating_hours, t.equipment_list, t.artist_roster, t.talent_roster, t.courses, t.capacity, t.venue_features) IS NOT DISTINCT FROM (r.profile_id, r.business_address, r.operating_hours, r.equipment_list, r.artist_roster, r.talent_roster, r.courses, r.capacity, r.venue_features))
     <> jsonb_array_length(payload) THEN
    RAISE EXCEPTION 'profile_business import: stored rows differ from the payload';
  END IF;
END
$import$;

