:false,"sort_order":3}]$json$;
BEGIN
  INSERT INTO public.profile_members (id, profile_id, kind, name, role, experience, is_leader, sort_order)
  SELECT r.id, r.profile_id, r.kind, r.name, r.role, r.experience, r.is_leader, r.sort_order FROM jsonb_to_recordset(payload) AS r(id uuid, profile_id uuid, kind text, name text, role text, experience text, is_leader boolean, sort_order int)
  ON CONFLICT (id) DO UPDATE SET profile_id = EXCLUDED.profile_id, kind = EXCLUDED.kind, name = EXCLUDED.name, role = EXCLUDED.role, experience = EXCLUDED.experience, is_leader = EXCLUDED.is_leader, sort_order = EXCLUDED.sort_order;

  IF (SELECT count(*) FROM jsonb_to_recordset(payload) AS r(id uuid, profile_id uuid, kind text, name text, role text, experience text, is_leader boolean, sort_order int) JOIN public.profile_members t ON t.id = r.id
      WHERE (t.id, t.profile_id, t.kind, t.name, t.role, t.experience, t.is_leader, t.sort_order) IS NOT DISTINCT FROM (r.id, r.profile_id, r.kind, r.name, r.role, r.experience, r.is_leader, r.sort_order))
     <> jsonb_array_length(payload) THEN
    RAISE EXCEPTION 'profile_members import: stored rows differ from the payload';
  END IF;
END
$import$;

