BEGIN
  INSERT INTO public.profile_events (id, profile_id, title, event_date, venue_name, sort_order)
  SELECT r.id, r.profile_id, r.title, r.event_date, r.venue_name, r.sort_order FROM jsonb_to_recordset(payload) AS r(id uuid, profile_id uuid, title text, event_date date, venue_name text, sort_order int)
  ON CONFLICT (id) DO UPDATE SET profile_id = EXCLUDED.profile_id, title = EXCLUDED.title, event_date = EXCLUDED.event_date, venue_name = EXCLUDED.venue_name, sort_order = EXCLUDED.sort_order;

  IF (SELECT count(*) FROM jsonb_to_recordset(payload) AS r(id uuid, profile_id uuid, title text, event_date date, venue_name text, sort_order int) JOIN public.profile_events t ON t.id = r.id
      WHERE (t.id, t.profile_id, t.title, t.event_date, t.venue_name, t.sort_order) IS NOT DISTINCT FROM (r.id, r.profile_id, r.title, r.event_date, r.venue_name, r.sort_order))
